const tasks = [];
for (const item of $input.all()) {
  tasks.push(item.json.row[0])
}
return [
  {
    'tasks': tasks
  }
];

const tasks = $input.first().json.tasks
const layout = $input.first().json.layout
return tasks.map(task => ({
  'prompt': layout.replace('{{PRODUIT}}', task),
}))

const responses = $input.all();
const separator = '\n\n***\n***\n***\n\n';
let combinedText = ''

responses.forEach((response, index) => {
  const content = response.json.text || '';

  if (index === 0) {
    combinedText += content;
  } else {
    combinedText += `${separator}${content}`;
  }
});

return {
  text: combinedText
};
